export type FlightModelParameterMap<T> =
    T extends b747
       ? b747SimProps
        : T extends c172
           ? c172SimProps
            : T extends graphics
               ? graphicsSimProps
                : never

export function getFlightModelParameters<
    T extends b747 | c172 | graphics,
>(module: T): FlightModelParameterMap<T> {
    switch (module.name.toLowerCase()) {
      case 'b747':
        return get_Parameters_b747(module as b747) as FlightModelParameterMap<T>
      case 'c172':
        return get_Parameters_c172(module as c172) as FlightModelParameterMap<T>
      case 'graphics':
        return get_Parameters_graphics(module as graphics) as FlightModelParameterMap<T>

      default:
        throw new Error('Unknown module');
     }
   }

export function getSimulationControlsParameters(module : ExtendedMainModule) : Record<string, SimulationProperties> {
  return get_Parameters_graphics(module.simulation);
} 
